function printCliHelp() {
  console.log(`PIO Agent \u2014 PlatformIO MCP server with web dashboard

USAGE:
  pio-agent                            Start MCP stdio server (default \u2014 for AI agents)
  pio-agent dashboard                  Open the web dashboard in your browser
  pio-agent install --cline            Install into Cline (VS Code extension or CLI)
  pio-agent install --claude           Install into Claude Desktop
  pio-agent install --vscode           Install into VS Code native MCP support
  pio-agent install --antigravity      Install into Google Antigravity
  pio-agent install --codex            Install into OpenAI Codex CLI
  pio-agent install --codex-plugin     Install the full Codex Plugin and skills

  The legacy platformio-mcp executable is an equivalent alias.

FLAGS (when starting MCP server):
  --open-dashboard-on-start            Auto-open dashboard when agent connects
  --disable-dashboard                  Disable web dashboard entirely
  --help                               Show this help
  --version                            Print version

ENV VARS:
  PORTAL_PORT                          Override dashboard port (default: 8080)
  PIO_MCP_OPEN_DASH_ON_START           Same as --open-dashboard-on-start
  PIO_MCP_DISABLE_DASHBOARD            Same as --disable-dashboard
`);
}
async function main() {
  const cliArgs = process.argv.slice(2);
  const subcommand = cliArgs.find((a) => !a.startsWith("--"));
  if (cliArgs.includes("--help") || subcommand === "help") {
    printCliHelp();
    process.exit(0);
  }
  if (cliArgs.includes("--version") || subcommand === "version") {
    let version3 = "unknown";
    try {
      const currentDir = path26.dirname(new URL(import.meta.url).pathname);
      const pkg = JSON.parse(
        fs29.readFileSync(path26.join(currentDir, "..", "package.json"), "utf8")
      );
      version3 = pkg.version;
    } catch {
    }
    console.log(version3);
    process.exit(0);
  }
  if (subcommand === "dashboard") {
    const result = await getDashboardStatusCore({ open: true });
    console.log(`PIO Agent Dashboard: ${result.secureLink}`);
    console.log(`Press Ctrl+C to stop.`);
    return;
  }
  if (subcommand === "install") {
    const target = cliArgs.find((a) => a.startsWith("--"))?.replace(/^--/, "");
    if (!target) {
      console.error(
        "Usage: pio-agent install --<cline|claude|vscode|antigravity|codex|codex-plugin>"
      );
      process.exit(1);
    }
    try {
      const currentDir = path26.dirname(new URL(import.meta.url).pathname);
      const installerEntry = path26.join(
        currentDir,
        "..",
        "scripts",
        "installers",
        "index.js"
      );
      const installerUrl = new URL(`file://${installerEntry}`).href;
      const { runInstaller } = await import(installerUrl);
      await runInstaller(target);
    } catch (e) {
      console.error(`Installer failed: ${e.message}`);
      process.exit(1);
    }
    process.exit(0);
  }
  if (subcommand && subcommand !== "help") {
    console.error(`Unknown subcommand: ${subcommand}`);
    printCliHelp();
    process.exit(1);
  }
  let isInstalled = false;
  try {
    isInstalled = await checkPlatformIOInstalled();
  } catch (error2) {
    const message = error2 instanceof Error ? error2.message : String(error2);
    await logDiagnostic(`Warning: PlatformIO availability check failed: ${message}`);
  }
  if (!isInstalled) {
    logDiagnostic(
      "Warning: PlatformIO CLI not found. Please install it from https://platformio.org/install/cli"
    );
    logDiagnostic(
      "The server will start but commands will fail until PlatformIO is installed.\n"
    );
  }
  const transport = new StdioServerTransport();
  await server.connect(transport);
  try {
    const { rehydrateMonitors: rehydrateMonitors2 } = await Promise.resolve().then(() => (init_monitor(), monitor_exports));
    const { getWorkspaces: getWorkspaces2 } = await Promise.resolve().then(() => (init_workspace_registry(), workspace_registry_exports));
    await rehydrateMonitors2();
    const workspaces = await getWorkspaces2();
    if (workspaces.length > 0 && !portalEvents.getLastKnownWorkspace()) {
      portalEvents.emitWorkspaceState(workspaces[workspaces.length - 1]);
    }
  } catch (e) {
    logDiagnostic(`[Server Reboot] Boot rehydration encountered an error: ${e}`);
  }
  if (process.argv.includes("--open-dashboard-on-start") || process.env.PIO_MCP_OPEN_DASH_ON_START === "true") {
    getDashboardStatusCore({ open: true }).catch(
      (e) => logDiagnostic(`[Dashboard] ${e.message}`)
    );
  }
  let gitHash = "unknown";
  try {
    const currentDir = path26.dirname(new URL(import.meta.url).pathname);
    gitHash = execSync4("git rev-parse --short HEAD", {
      cwd: currentDir,
      stdio: "pipe"
    }).toString().trim();
  } catch {
  }
  let version2 = "1.0.0";
  try {
    const currentDir = path26.dirname(new URL(import.meta.url).pathname);
    const pkg = JSON.parse(
      fs29.readFileSync(path26.join(currentDir, "../package.json"), "utf8")
    );
    version2 = pkg.version;
  } catch {
  }
  logDiagnostic("\n\n=======================================================");
  logDiagnostic(
    `\u{1F680} PIO Agent v${version2} (Build: ${gitHash}) running on stdio`
  );
  logDiagnostic("\u{1F680} Server supports 1000+ boards across 30+ platforms");
  logDiagnostic("=======================================================\n");
}
